def choose_strategy(self, analysis: Dict) -> CompressionStrategy:
    """Escolhe estratégia baseado na análise."""
    if analysis.get('is_noisy_data', False):
        return CompressionStrategy.LUMINIDIO
    elif analysis['sparsity'] > 0.5:
        return CompressionStrategy.SPARSE
    elif analysis['delta_efficiency'] > 0.3 and analysis.get('delta_autocorr', 0) > 0.2:
        return CompressionStrategy.DELTA
    else:
        return CompressionStrategy.STANDARD

