def reconstruct(self, selected_atoms):
    """Reconstrói o sinal a partir dos átomos selecionados."""
    if self.use_torch:
        result = torch.zeros(self.n, device=self.device, dtype=torch.float64)
        for atom_info in selected_atoms:
            idx = atom_info['index']
            coef = atom_info['coefficient']
            result += coef * self.atoms_matrix[idx]
        return result
    else:
        result = np.zeros(self.n)
